/**
 * testFixtures.ts
 *
 * Synthetic scanner test fixtures for the Developer Test Lab.
 * Each fixture defines the expected extraction output for a synthetic document
 * generated by `generateSyntheticDocument()`.
 */

// ─── Types ────────────────────────────────────────────────────────────────────

export type FixtureCategory = 'Banking' | 'Income' | 'Debts' | 'Investments' | 'Bills' | 'File Types';
export type ToleranceType = 'dollar' | 'percentage' | 'hours' | 'text' | 'date';
export type DestSection = 'assets' | 'debts' | 'bills' | 'paystubs' | 'skip';

export interface ExpectedField {
  value: string | number;
  tolerance?: number;
  toleranceType?: ToleranceType;
}

export interface ScannerTestFixture {
  id: string;
  name: string;
  category: FixtureCategory;
  /** MIME type for the generated file */
  mimeType: 'image/jpeg' | 'image/png';
  /** Filename extension (may differ from mimeType for File Types category) */
  fileExtension: string;
  expectedDocType: string;
  expectedInstitution?: string;
  /** Fields expected in scan result — key matches API field names */
  expectedFields: Record<string, ExpectedField>;
  expectedDestination: DestSection;
  /** If true, also exercise buildUpdatePlan + applyUpdatePlan */
  fullFlowCheck?: boolean;
}

// ─── Canvas document generator ────────────────────────────────────────────────

export interface DocSpec {
  institution: string;
  docType: string;
  accountNumber: string;
  statementDate: string;
  /** Display rows: label → display value */
  rows: Array<[string, string]>;
}

/** Build the display rows from fixture expected fields for the canvas renderer. */
function buildDocSpec(fixture: ScannerTestFixture): DocSpec {
  const labelMap: Record<string, string> = {
    currentBalance:    'Current Balance',
    availableBalance:  'Available Balance',
    closingBalance:    'Closing Balance',
    accountType:       'Account Type',
    grossPay:          'Gross Pay',
    netPay:            'Net Pay',
    regularHours:      'Regular Hours',
    overtimeHours:     'Overtime Hours',
    taxes:             'Taxes Withheld',
    deductions:        'Deductions',
    perDiem:           'Per Diem',
    employer:          'Employer',
    balance:           'Account Balance',
    currentBalance2:   'Current Balance',
    principalBalance:  'Principal Balance',
    statementBalance:  'Statement Balance',
    interestRate:      'Annual Percentage Rate',
    apr:               'APR',
    minimumPayment:    'Minimum Payment',
    monthlyPayment:    'Monthly Payment',
    amountDue:         'Amount Due',
    dueDate:           'Due Date',
    provider:          'Provider',
    totalValue:        'Total Account Value',
    vestedBalance:     'Vested Balance',
    planName:          'Plan Name',
    employer401k:      'Employer',
    interestEarned:    'Interest Earned',
    maturityDate:      'Maturity Date',
    creditLimit:       'Credit Limit',
    paymentDue:        'Payment Due Date',
    loanAmount:        'Original Loan Amount',
  };

  const rows: Array<[string, string]> = [];
  for (const [key, ef] of Object.entries(fixture.expectedFields)) {
    const label = labelMap[key] ?? key.replace(/([A-Z])/g, ' $1').trim();
    const v = ef.value;
    let display: string;
    if (typeof v === 'number') {
      const tt = ef.toleranceType ?? 'dollar';
      if (tt === 'dollar') display = `$${v.toFixed(2)}`;
      else if (tt === 'percentage') display = `${v}%`;
      else if (tt === 'hours') display = `${v} hrs`;
      else display = String(v);
    } else {
      display = v;
    }
    rows.push([label, display]);
  }
  return {
    institution: fixture.expectedInstitution ?? 'Financial Institution',
    docType: fixture.expectedDocType,
    accountNumber: '****' + (4000 + parseInt(fixture.id.replace(/\D/g, '').slice(0, 4) || '1', 10) % 9000).toString(),
    statementDate: 'July 1, 2026',
    rows,
  };
}

/**
 * Generate a synthetic financial document as a File using the HTML5 Canvas API.
 * The output is a JPEG or PNG image with enough text for the Vision API to
 * classify and extract fields.
 */
export async function generateSyntheticDocument(
  fixture: ScannerTestFixture,
  spec?: Partial<DocSpec>,
): Promise<File> {
  const canvas = document.createElement('canvas');
  canvas.width = 820;
  canvas.height = 620;
  const ctx = canvas.getContext('2d')!;
  const ds = { ...buildDocSpec(fixture), ...spec };

  // White background
  ctx.fillStyle = '#ffffff';
  ctx.fillRect(0, 0, canvas.width, canvas.height);

  // Header bar
  ctx.fillStyle = '#0d2d4e';
  ctx.fillRect(0, 0, canvas.width, 85);

  // Institution name
  ctx.fillStyle = '#ffffff';
  ctx.font = 'bold 22px Arial, sans-serif';
  ctx.fillText(ds.institution, 28, 38);

  // Document type subtitle
  ctx.font = '15px Arial, sans-serif';
  ctx.fillStyle = '#a8c8e8';
  ctx.fillText(ds.docType.toUpperCase(), 28, 65);

  // Thin accent line
  ctx.fillStyle = '#1e7bc4';
  ctx.fillRect(0, 85, canvas.width, 4);

  // Account info row
  ctx.fillStyle = '#555555';
  ctx.font = '13px Arial, sans-serif';
  ctx.fillText(`Account Number: ${ds.accountNumber}`, 28, 115);
  ctx.fillText(`Statement Date: ${ds.statementDate}`, 420, 115);

  // Divider
  ctx.strokeStyle = '#e0e0e0';
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.moveTo(28, 130);
  ctx.lineTo(canvas.width - 28, 130);
  ctx.stroke();

  // Field rows
  let y = 162;
  const COL_LABEL = 28;
  const COL_VALUE = 380;

  for (const [label, value] of ds.rows) {
    if (y > canvas.height - 60) break;

    // Zebra stripe
    if ((ds.rows.indexOf([label, value]) + 0) % 2 === 0) {
      ctx.fillStyle = '#f8f9fa';
      ctx.fillRect(0, y - 18, canvas.width, 28);
    }

    ctx.fillStyle = '#666666';
    ctx.font = '13px Arial, sans-serif';
    ctx.fillText(label + ':', COL_LABEL, y);

    ctx.fillStyle = '#111111';
    ctx.font = 'bold 13px Arial, sans-serif';
    ctx.fillText(value, COL_VALUE, y);

    y += 30;
  }

  // Footer
  ctx.fillStyle = '#999999';
  ctx.font = '11px Arial, sans-serif';
  ctx.fillText('CONFIDENTIAL — For authorized account holder use only', 28, canvas.height - 18);

  // Watermark with doc type for AI clarity
  ctx.save();
  ctx.globalAlpha = 0.04;
  ctx.font = 'bold 48px Arial, sans-serif';
  ctx.fillStyle = '#000000';
  ctx.translate(canvas.width / 2, canvas.height / 2);
  ctx.rotate(-0.3);
  ctx.fillText(ds.docType, -200, 0);
  ctx.restore();

  const mimeType = fixture.mimeType;
  const ext = fixture.fileExtension;
  const filename = `${fixture.id.replace(/_/g, '-')}-statement.${ext}`;

  return new Promise<File>((resolve, reject) => {
    canvas.toBlob(
      blob => {
        if (!blob) return reject(new Error('Canvas toBlob returned null'));
        resolve(new File([blob], filename, { type: mimeType }));
      },
      mimeType,
      0.92,
    );
  });
}

