/** Convenience accessor: all unique categories in fixture order */
export const FIXTURE_CATEGORIES: FixtureCategory[] = [
  'Banking', 'Income', 'Debts', 'Investments', 'Bills', 'File Types',
];

/** Look up a fixture by id */
export function getFixture(id: string): ScannerTestFixture | undefined {
  return FIXTURES.find(f => f.id === id);
}
